package exercise

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestGreetHandlerGreetsTheName(t *testing.T) {
	request := httptest.NewRequest(http.MethodGet, "/greet?name=Ada", nil)
	recorder := httptest.NewRecorder()

	GreetHandler(recorder, request)
	result := recorder.Result()

	if result.StatusCode != http.StatusOK {
		t.Errorf("got status %d, want %d", result.StatusCode, http.StatusOK)
	}

	if got := result.Header.Get("Content-Type"); got != "application/json" {
		t.Errorf("got content type %q, want %q", got, "application/json")
	}

	var payload struct {
		Greeting string `json:"greeting"`
	}
	if err := json.Unmarshal(recorder.Body.Bytes(), &payload); err != nil {
		t.Fatalf("could not read the reply as json: %v (body was %q)", err, recorder.Body.String())
	}
	if payload.Greeting != "Hello, Ada" {
		t.Errorf("got greeting %q, want %q", payload.Greeting, "Hello, Ada")
	}
}

