func TestGreetHandlerRejectsAMissingName(t *testing.T) {
	request := httptest.NewRequest(http.MethodGet, "/greet", nil)
	recorder := httptest.NewRecorder()

	GreetHandler(recorder, request)
	result := recorder.Result()

	if result.StatusCode != http.StatusBadRequest {
		t.Errorf("got status %d, want %d", result.StatusCode, http.StatusBadRequest)
	}

	if got := result.Header.Get("Content-Type"); got != "text/plain; charset=utf-8" {
		t.Errorf("got content type %q, want %q", got, "text/plain; charset=utf-8")
	}

	if got := result.Header.Get("X-Content-Type-Options"); got != "nosniff" {
		t.Errorf("got X-Content-Type-Options %q, want %q", got, "nosniff")
	}

	if got := recorder.Body.String(); got != "name is required\n" {
		t.Errorf("got body %q, want %q", got, "name is required\n")
	}
}

func TestGreetHandlerRejectsAnEmptyName(t *testing.T) {
	request := httptest.NewRequest(http.MethodGet, "/greet?name=", nil)
	recorder := httptest.NewRecorder()

	GreetHandler(recorder, request)

	if recorder.Result().StatusCode != http.StatusBadRequest {
		t.Errorf("got status %d, want %d", recorder.Result().StatusCode, http.StatusBadRequest)
	}
}

